function buildMetadata(): Plugin {
  return {
    name: 'app-build-metadata',
    apply: 'build',
    config() { return { define: { __BUILD_SHA__: JSON.stringify(process.env.GIT_SHA ?? 'dev') } }; },
  };
}

export default defineConfig({ plugins: [react(), buildMetadata()] });

function featureFlags(): Plugin {
  const publicId = 'virtual:feature-flags';
  const resolvedId = '\0' + publicId;
  return {
    name: 'feature-flags',
    resolveId(id) { if (id === publicId) return resolvedId; },
    load(id) { if (id === resolvedId) return `export default ${JSON.stringify(loadFlags())}`; },
  };
}

